(function(){
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const url=s=>/^(https:\/\/[^\s]+|\/[a-z0-9][^\s]*|#[^\s]+)$/i.test(s||'')?s:'';
 function create(api){
  let settings={enabled:false,interval:5,slides:[],promos:[],categories:[]},products=[],timer=null,draft=null,paused=false,index=0,busy=false;
  const picture=(item,cls='')=>`<picture>${url(item.mobile_url)?`<source media="(max-width:620px)" srcset="${esc(url(item.mobile_url))}">`:''}<img class="${cls}" src="${esc(url(item.image_url))}" alt="${esc(item.title||'Marketplace collection')}" loading="lazy"></picture>`;
  const media=item=>url(item.link)?`<a href="${esc(url(item.link))}">${picture(item)}</a>`:picture(item);
  function show(i){const host=document.getElementById('carouselPartTwo');if(!host)return;const slides=[...host.querySelectorAll('.secondary-slide')];if(!slides.length)return;index=(i+slides.length)%slides.length;slides.forEach((s,n)=>{s.hidden=n!==index;s.setAttribute('aria-hidden',String(n!==index))});}
  function render(){
   const anchor=document.getElementById('featured')?.closest('.section');if(!anchor)return;
   let root=document.getElementById('premiumDiscovery');if(!root){anchor.insertAdjacentHTML('afterend','<div id="premiumDiscovery" class="shop-home-section"></div>');root=document.getElementById('premiumDiscovery');}
   root.classList.toggle('hidden',!!document.querySelector('[data-shop-view="vendors"].active,[data-shop-view="categories"].active'));
   const slides=settings.enabled?(settings.slides||[]).filter(x=>x.enabled&&url(x.image_url)):[],promos=(settings.promos||[]).filter(x=>x.enabled&&url(x.image_url));
   const vendors=[...new Map(products.map(p=>[p.vendor_id,{id:p.vendor_id,...p.vendors}])).values()];
   root.innerHTML=`${slides.length?`<section id="carouselPartTwo" class="secondary-carousel" aria-label="Marketplace collections carousel">${slides.map((item,i)=>`<div class="secondary-slide" ${i?'hidden':''}>${media(item)}</div>`).join('')}${slides.length>1?`<button class="carousel-pause" type="button" aria-label="${paused?'Resume':'Pause'} collection carousel" aria-pressed="${paused}">${paused?'▶':'Ⅱ'}</button>`:''}</section>`:''}${promos.length?`<section class="premium-promos" aria-label="Featured collections">${promos.map(item=>`<div>${media(item)}</div>`).join('')}</section>`:''}${vendors.length?`<section class="premium-vendors section"><header><div><span class="eyebrow">SHOP BY SELLER</span><h2>Discover vendors</h2></div><button type="button" class="text-button" data-shop-view="vendors">View all →</button></header><div class="premium-vendor-row">${vendors.map(v=>`<button type="button" data-directory-vendor="${esc(v.id)}">${url(v.logo_url)?`<img src="${esc(v.logo_url)}" alt="" loading="lazy">`:`<span class="premium-vendor-initial">${esc((v.business_name||'Store').slice(0,2))}</span>`}<span><strong>${esc(v.business_name||'Store')}</strong><small>Visit store →</small></span></button>`).join('')}</div></section>`:''}`;
   clearInterval(timer);index=0;const pause=root.querySelector('.carousel-pause');if(pause)pause.onclick=()=>{paused=!paused;pause.textContent=paused?'▶':'Ⅱ';pause.setAttribute('aria-label',(paused?'Resume':'Pause')+' collection carousel');pause.setAttribute('aria-pressed',String(paused))};
   if(slides.length>1&&!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)timer=setInterval(()=>{if(!paused&&!document.hidden&&!root.classList.contains('hidden')&&document.getElementById('page-shop')?.classList.contains('active')&&!root.contains(document.activeElement)&&!root.matches(':hover'))show(index+1)},Math.max(3,Number(settings.interval)||5)*1000);
   renderPrimaryMedia();applyCategoryImages();
  }
  function applyCategoryImages(){document.querySelectorAll('[data-pick-category],.featured-category-card,[data-directory-category].category-directory-card').forEach(card=>{const name=card.dataset.pickCategory||card.dataset.directoryCategory,custom=(settings.categories||[]).find(c=>c.name===name&&c.enabled),image=card.querySelector('img');if(image){const src=api.categoryIcon?.(name);if(src)image.src=src;image.alt=name||'Category';image.classList.remove('collection-photo');image.classList.add('category-illustration');}card.onclick=url(custom?.link)?e=>{e.preventDefault();e.stopPropagation();location.assign(url(custom.link));}:null;});}
  async function load(items){products=items;const r=await api.db.rpc('marketplace_presentation_settings');if(!r.error&&r.data){settings=r.data;}render();}
  function renderPrimaryMedia(){
   if(Array.isArray(settings.main))api.main?.(settings.main,settings.main_interval||3);
   let host=document.getElementById('promotionVideo');const anchor=document.getElementById('marketTicker')||document.getElementById('marketHero');
   if(!host&&anchor){anchor.insertAdjacentHTML('afterend','<section id="promotionVideo" class="shop-home-section promotion-video"></section>');host=document.getElementById('promotionVideo');}
   if(!host)return;const v=(settings.video||[]).find(v=>v.enabled&&url(v.video_url));host.hidden=!v;
   host.classList.toggle('hidden',!!document.querySelector('[data-shop-view="vendors"].active,[data-shop-view="categories"].active'));
   host.innerHTML=v?`<video controls playsinline preload="metadata" poster="${esc(url(window.matchMedia?.('(max-width:620px)').matches?v.mobile_url||v.image_url:v.image_url))}" aria-label="${esc(v.title||'Promotion video')}"><source src="${esc(url(v.mobile_video_url)||url(v.video_url))}" media="(max-width:620px)"><source src="${esc(url(v.video_url))}"></video>${url(v.link)?`<a class="btn primary" href="${esc(url(v.link))}">Visit Promotion →</a>`:''}`:'';
  }
  const sizes={main:['1920 × 720 px','900 × 900 px'],slides:['1920 × 360 px','900 × 300 px'],promos:['960 × 480 px','900 × 600 px'],video:['1920 × 1080 px','720 × 1280 px'],categories:['600 × 600 px','600 × 600 px']};
  async function upload(file,video=false){
   const types=video?{'video/mp4':'mp4','video/webm':'webm'}:{'image/jpeg':'jpg','image/png':'png','image/webp':'webp'};
   if(!types[file.type]||file.size>(video?26214400:5242880))throw Error(video?'Choose MP4 or WebM up to 25 MB':'Choose JPG, PNG or WebP up to 5 MB');
   const path=`notices/promotion-${crypto.randomUUID()}.${types[file.type]}`,r=await api.db.storage.from('site-announcements').upload(path,file,{contentType:file.type,upsert:false});if(r.error)throw r.error;
   return api.db.storage.from('site-announcements').getPublicUrl(path).data.publicUrl;
  }
  async function mountAdmin(){
   if(document.getElementById('premiumAdmin'))return;const hero=document.getElementById('heroBannerForm')?.closest('.card');if(!hero)return;
   const r=await api.db.rpc('marketplace_presentation_settings');if(r.error)throw r.error;settings=r.data||settings;
   draft=JSON.parse(JSON.stringify(settings));draft.main??=(api.hero?.()||[]).map(x=>({...x,link:x.link||x.cta_link||'#shop',enabled:x.enabled!==false}));draft.video??=[];draft.main_interval??=3;
   hero.hidden=true;hero.classList.add('legacy-promotion-editor');hero.insertAdjacentHTML('afterend','<section id="premiumAdmin" class="card premium-editor"></section>');renderAdmin();
  }
  function renderAdmin(){
   const host=document.getElementById('premiumAdmin');if(!host)return;
   const labels={main:'Main Carousel',video:'Video Promotion',slides:'Carousel Part Two',promos:'Side-by-Side Promotions',categories:'Collection Images'},limits={main:8,video:1,slides:8,promos:2,categories:60};
   const uploadField=(kind,i,item,field,label,mobile=false,video=false)=>`<label class="media-upload-field">${label}<small>Recommended: ${sizes[kind][mobile?1:0]} · ${video?'MP4 / WebM · up to 25 MB':'JPG / PNG / WebP · up to 5 MB'}</small><input type="file" data-upload="${field}" accept="${video?'video/mp4,video/webm':'image/jpeg,image/png,image/webp'}"><input aria-label="${label} URL" data-field="${field}" value="${esc(item[field]||'')}" placeholder="Or paste an HTTPS media URL"><small data-dimensions="${field}">${mobile?'Optional — desktop artwork is used if empty.':'Full artwork is shown without cropping.'}</small></label>`;
   host.innerHTML=`<div class="card-head"><div><h2>Promotional Banners & Media</h2><p>Choose a placement, upload artwork, add its destination and save.</p></div></div><div class="card-body"><div class="premium-editor-settings"><label><input type="checkbox" id="secondCarouselEnabled" ${draft.enabled?'checked':''}> Show Carousel Part Two</label><label>Main rotation (seconds)<input id="mainCarouselInterval" type="number" min="3" max="15" value="${draft.main_interval}"></label><label>Second rotation (seconds)<input id="secondCarouselInterval" type="number" min="3" max="15" value="${draft.interval}"></label></div>${Object.keys(labels).map(kind=>`<section class="premium-editor-group" data-kind="${kind}"><header><div><h3>${labels[kind]}</h3><small>${kind==='video'?'Playback controls and a separate destination button.':'Every image can have its own destination.'}</small></div><button type="button" class="btn small" data-promo-add="${kind}" ${draft[kind].length>=limits[kind]?'disabled':''}>Add ${kind==='video'?'video':'image'}</button></header><div class="promotion-admin-list">${draft[kind].map((item,i)=>`<article class="promotion-edit-card"><header>${url(item.image_url)?`<img src="${esc(url(item.image_url))}" alt="${esc(item.title||'Promotion preview')}">`:'<span class="media-placeholder">Add media</span>'}<div><strong>${esc(item.title||item.name||'Untitled promotion')}</strong><small>${item.enabled?'Active':'Hidden'} · Position ${i+1}</small></div><div class="promotion-actions"><button type="button" class="btn small" data-promo-edit="${kind}:${i}" aria-expanded="false">Edit</button><button type="button" class="btn small" data-promo-up="${kind}:${i}" aria-label="Move ${esc(item.title||'promotion')} up" ${!i?'disabled':''}>↑</button><button type="button" class="btn small" data-promo-remove="${kind}:${i}">Remove</button></div></header><div id="premium-edit-${kind}-${i}" hidden><div class="premium-image-fields" data-kind="${kind}" data-index="${i}"><label>Internal title<input data-field="title" maxlength="120" value="${esc(item.title)}"></label>${kind==='categories'?`<label>Category<select data-field="name"><option value="">Choose category</option>${api.categories().map(c=>`<option ${c===item.name?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`:''}${uploadField(kind,i,item,'image_url',kind==='video'?'Video cover image':'Desktop image')}${kind==='video'?uploadField(kind,i,item,'mobile_url','Mobile video cover',true)+uploadField(kind,i,item,'video_url','Desktop video',false,true)+uploadField(kind,i,item,'mobile_video_url','Mobile video',true,true):kind!=='categories'?uploadField(kind,i,item,'mobile_url','Mobile image',true):''}<label>Destination link<input data-field="link" value="${esc(item.link||'')}" placeholder="Paste a vendor, product or promotion URL"><button type="button" class="btn small" data-test-link>Test link ↗</button><small>Example: #vendor/vendor-id. HTTPS URLs and site links are supported.</small></label><label><input type="checkbox" data-field="enabled" ${item.enabled?'checked':''}> Active</label><div class="promotion-preview-pair"><div><small>Desktop preview</small><img data-preview="image_url" src="${esc(url(item.image_url))}" alt="Desktop artwork preview"></div>${kind!=='categories'?`<div><small>Mobile preview</small><img data-preview="mobile_url" src="${esc(url(item.mobile_url)||url(item.image_url))}" alt="Mobile artwork preview"></div>`:''}</div></div></div></article>`).join('')||'<p class="promotion-empty">Nothing added yet. Use the Add button to begin.</p>'}</div></section>`).join('')}<div class="promotion-save"><button type="button" class="btn primary" id="savePremiumPresentation">Save promotions</button><p role="status" id="premiumSaveStatus">Edits remain drafts until you save. Different image sizes are fitted fully, never cropped.</p></div></div>`;
   host.querySelector('#secondCarouselEnabled').onchange=e=>draft.enabled=e.target.checked;
   host.querySelector('#secondCarouselInterval').oninput=e=>draft.interval=Number(e.target.value);
   host.querySelector('#mainCarouselInterval').oninput=e=>draft.main_interval=Number(e.target.value);
   const lock=on=>{busy=on;host.querySelectorAll('button,input,select').forEach(e=>{if(on){e.dataset.wasDisabled=String(e.disabled);e.disabled=true;}else{e.disabled=e.dataset.wasDisabled==='true';delete e.dataset.wasDisabled;}});};
   const refreshPreview=box=>{const item=draft[box.dataset.kind][Number(box.dataset.index)];box.querySelectorAll('[data-preview]').forEach(img=>{const src=url(item[img.dataset.preview])||url(item.image_url);if(src)img.src=src;else img.removeAttribute('src');});};
   host.querySelectorAll('[data-field]').forEach(input=>input.oninput=()=>{const box=input.closest('[data-index]');draft[box.dataset.kind][Number(box.dataset.index)][input.dataset.field]=input.type==='checkbox'?input.checked:input.value;refreshPreview(box);});
   host.querySelectorAll('[data-test-link]').forEach(b=>b.onclick=()=>{const link=url(b.closest('[data-index]').querySelector('[data-field="link"]').value),status=host.querySelector('#premiumSaveStatus');if(!link){status.textContent='Enter an HTTPS URL or site link first.';return;}window.open(link,'_blank','noopener,noreferrer');});
   host.querySelectorAll('[data-upload]').forEach(input=>input.onchange=async()=>{const file=input.files?.[0];if(!file||busy)return;const status=host.querySelector('#premiumSaveStatus'),box=input.closest('[data-index]');lock(true);status.textContent='Uploading…';try{const video=input.dataset.upload.includes('video'),image=await upload(file,video);draft[box.dataset.kind][Number(box.dataset.index)][input.dataset.upload]=image;box.querySelector(`[data-field="${input.dataset.upload}"]`).value=image;refreshPreview(box);if(!video){const bitmap=await createImageBitmap(file);box.querySelector(`[data-dimensions="${input.dataset.upload}"]`).textContent=`Uploaded: ${bitmap.width} × ${bitmap.height} px · full image will be visible`;bitmap.close();}status.textContent='Uploaded. Check the previews and save promotions.';}catch(err){status.textContent=err.message;}finally{lock(false);}});
   host.querySelectorAll('[data-promo-add]').forEach(b=>b.onclick=()=>{if(busy)return;const kind=b.dataset.promoAdd;draft[kind].push({title:'',name:'',image_url:'',mobile_url:'',video_url:'',mobile_video_url:'',link:'',enabled:true});renderAdmin();document.getElementById(`premium-edit-${kind}-${draft[kind].length-1}`).hidden=false;});
   for(const action of ['edit','up','remove'])host.querySelectorAll(`[data-promo-${action}]`).forEach(b=>b.onclick=()=>{if(busy)return;const [kind,position]=b.getAttribute('data-promo-'+action).split(':'),i=Number(position);if(action==='edit'){const row=document.getElementById(`premium-edit-${kind}-${i}`);row.hidden=!row.hidden;b.setAttribute('aria-expanded',String(!row.hidden));return;}if(action==='remove')draft[kind].splice(i,1);else if(i>0)[draft[kind][i-1],draft[kind][i]]=[draft[kind][i],draft[kind][i-1]];renderAdmin();});
   host.querySelector('#savePremiumPresentation').onclick=async()=>{if(busy)return;const status=host.querySelector('#premiumSaveStatus');lock(true);status.textContent='Saving…';try{const r=await api.db.rpc('admin_save_marketplace_presentation',{p_settings:draft});if(r.error)throw r.error;settings=JSON.parse(JSON.stringify(r.data));render();status.textContent='Saved. Promotions are live.';}catch(err){status.textContent=err.message||'Could not save';}finally{lock(false);}};
  }
  return {load,render,mountAdmin,applyCategoryImages};
 }
 window.MioPremium={create};
})();
